  1	import type { Actor, Role } from "@/types/member";
  2	import { ROLE_RANK } from "@/types/member";
  3	import type {
  4	  PermissionAction,
  5	  PermissionDecision,
  6	  PermissionResource,
  7	} from "@/types/permission";
  8	
  9	/**
 10	 * The single authorization entry point for Taskflow.
 11	 *
 12	 * Every Server Action, service method, Route Handler and permission-sensitive
 13	 * UI component funnels through `can()`. Nothing else may branch on
 14	 * `actor.role` directly — if you find yourself writing `role === "admin"`,
 15	 * add an action to `PermissionAction` and a row to `ROLE_MATRIX` instead.
 16	 *
 17	 * Decision order:
 18	 *   1. cross-tenant guard (`actor.orgId` must equal `resource.orgId`)
 19	 *   2. platform staff bypass
 20	 *   3. role matrix lookup
 21	 *   4. ownership escalations (authors edit their own issues/comments)
 22	 */
 23	
 24	/** Minimum role required for each action, before ownership escalations. */
 25	export const ROLE_MATRIX: Readonly<Record<PermissionAction, Role>> = {
 26	  "org:read": "viewer",
 27	  "org:update": "admin",
 28	  "org:delete": "owner",
 29	  "org:manage_billing": "owner",
 30	  "org:manage_flags": "admin",
 31	  "member:read": "viewer",
 32	  "member:invite": "admin",
 33	  "member:update_role": "admin",
 34	  "member:remove": "admin",
 35	  "project:create": "member",
 36	  "project:read": "viewer",
 37	  "project:update": "member",
 38	  "project:archive": "admin",
 39	  "project:delete": "owner",
 40	  "issue:create": "member",
 41	  "issue:read": "viewer",
 42	  "issue:update": "member",
 43	  "issue:assign": "member",
 44	  "issue:archive": "member",
 45	  "issue:delete": "admin",
 46	  "comment:create": "member",
 47	  "comment:read": "viewer",
 48	  "comment:update": "member",
 49	  "comment:delete": "admin",
 50	  "activity:read": "member",
 51	  "activity:export": "admin",
 52	  "notification:read": "viewer",
 53	  "notification:manage": "viewer",
 54	  "webhook:manage": "admin",
 55	};
 56	
 57	/** Actions an actor may perform on their own content regardless of role rank. */
 58	const OWNERSHIP_ESCALATIONS: Readonly<Partial<Record<PermissionAction, true>>> = {
 59	  "issue:update": true,
 60	  "issue:archive": true,
 61	  "comment:update": true,
 62	  "comment:delete": true,
 63	  "notification:manage": true,
 64	};
 65	
 66	function isOwnedByActor(
 67	  actor: Actor,
 68	  resource: PermissionResource,
 69	): boolean {
 70	  switch (resource.kind) {
 71	    case "issue":
 72	      return (
 73	        resource.authorId === actor.userId ||
 74	        resource.assigneeId === actor.userId
 75	      );
 76	    case "comment":
 77	      return resource.authorId === actor.userId;
 78	    case "project":
 79	      return resource.leadId === actor.userId;
 80	    case "notification":
 81	      return resource.recipientId === actor.userId;
 82	    case "member":
 83	      return resource.targetUserId === actor.userId;
 84	    default:
 85	      return false;
 86	  }
 87	}
 88	
 89	/**
 90	 * Answers "may this actor perform this action on this resource?".
 91	 *
 92	 * @param actor    the authenticated principal, always scoped to one org
 93	 * @param action   a member of the closed `PermissionAction` vocabulary
 94	 * @param resource the object being acted on, discriminated on `kind`
 95	 */
 96	export function can(
 97	  actor: Actor,
 98	  action: PermissionAction,
 99	  resource: PermissionResource,
100	): boolean {
101	  return explain(actor, action, resource).allowed;
102	}
103	
104	/** Same decision as `can()`, but reports why — used by the settings UI. */
105	export function explain(
106	  actor: Actor,
107	  action: PermissionAction,
108	  resource: PermissionResource,
109	): PermissionDecision {
110	  const base = { action, resourceKind: resource.kind } as const;
111	
112	  if (actor.orgId !== resource.orgId) {
113	    return { ...base, allowed: false, reason: "denied_cross_tenant" };
114	  }
115	
116	  if (actor.isPlatformStaff === true) {
117	    return { ...base, allowed: true, reason: "granted_by_staff" };
118	  }
119	
120	  const required = ROLE_MATRIX[action];
121	  if (required === undefined) {
122	    return { ...base, allowed: false, reason: "denied_unknown_action" };
123	  }
124	
125	  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
126	    return { ...base, allowed: true, reason: "granted_by_role" };
127	  }
128	
129	  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
130	    return { ...base, allowed: true, reason: "granted_by_ownership" };
131	  }
132	
133	  return { ...base, allowed: false, reason: "denied_by_role" };
134	}
135	
136	/** Thrown by `assertCan()`; mapped to a `forbidden` `ActionResult` by callers. */
137	export class PermissionDeniedError extends Error {
138	  readonly code = "forbidden" as const;
139	
140	  constructor(
141	    readonly action: PermissionAction,
142	    readonly decision: PermissionDecision,
143	  ) {
144	    super(`Permission denied: ${action} on ${decision.resourceKind}`);
145	    this.name = "PermissionDeniedError";
146	  }
147	}
148	
149	/** Throwing variant of `can()` for service-layer guard clauses. */
150	export function assertCan(
151	  actor: Actor,
152	  action: PermissionAction,
153	  resource: PermissionResource,
154	): void {
155	  const decision = explain(actor, action, resource);
156	  if (!decision.allowed) {
157	    throw new PermissionDeniedError(action, decision);
158	  }
159	}
160	
161	/** Bulk evaluation used by navigation and toolbar components. */
162	export function canAll(
163	  actor: Actor,
164	  actions: readonly PermissionAction[],
165	  resource: PermissionResource,
166	): boolean {
167	  return actions.every((action) => can(actor, action, resource));
168	}

  1	import type { OrgId, TenantScoped } from "@/types/common";
  2	import type { Actor } from "@/types/member";
  3	
  4	/**
  5	 * Multi-tenancy invariant helpers.
  6	 *
  7	 * Every repository query must be filtered by `org_id`, and every row that
  8	 * crosses a service boundary must be re-checked against the actor's org. These
  9	 * helpers are the only sanctioned way to express that — a hand-written
 10	 * `if (row.orgId !== actor.orgId)` is a review failure.
 11	 */
 12	
 13	export class TenantScopeError extends Error {
 14	  readonly code = "tenant_scope_violation" as const;
 15	
 16	  constructor(
 17	    readonly expectedOrgId: OrgId,
 18	    readonly actualOrgId: OrgId,
 19	  ) {
 20	    super(
 21	      `Tenant scope violation: expected org ${expectedOrgId}, got ${actualOrgId}`,
 22	    );
 23	    this.name = "TenantScopeError";
 24	  }
 25	}
 26	
 27	/** Throws unless `orgId` belongs to the actor's organization. */
 28	export function assertOrgScope(actor: Actor, orgId: OrgId): void {
 29	  if (actor.orgId !== orgId) {
 30	    throw new TenantScopeError(actor.orgId, orgId);
 31	  }
 32	}
 33	
 34	/** Throws unless every supplied row belongs to the actor's organization. */
 35	export function assertRowsInScope<T extends TenantScoped>(
 36	  actor: Actor,
 37	  rows: readonly T[],
 38	): void {
 39	  for (const row of rows) {
 40	    assertOrgScope(actor, row.orgId);
 41	  }
 42	}
 43	
 44	/** Non-throwing predicate, for filtering rather than failing. */
 45	export function isInOrgScope(actor: Actor, row: TenantScoped): boolean {
 46	  return row.orgId === actor.orgId;
 47	}
 48	
 49	/** Narrows a nullable row to one the actor may see; `null` otherwise. */
 50	export function scopedOrNull<T extends TenantScoped>(
 51	  actor: Actor,
 52	  row: T | null | undefined,
 53	): T | null {
 54	  if (!row) return null;
 55	  return row.orgId === actor.orgId ? row : null;
 56	}
 57	
 58	/**
 59	 * Wraps an arbitrary filter object with the actor's `orgId`, so repositories
 60	 * cannot forget it. Always spread the caller filter first.
 61	 */
 62	export function withOrgScope<T extends object>(
 63	  actor: Actor,
 64	  filter: T,
 65	): T & { orgId: OrgId } {
 66	  return { ...filter, orgId: actor.orgId };
 67	}

  1	/**
  2	 * Maps thrown domain errors onto `AppErrorShape`.
  3	 *
  4	 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
  5	 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
  6	 * `ZodError`); Server Actions and Route Handlers never propagate those to the
  7	 * client. Everything funnels through `toAppError()` so one thrown class maps
  8	 * to exactly one `ErrorCode` and one HTTP status, app-wide.
  9	 */
 10	import { FeatureDisabledError } from "@/lib/feature-flags";
 11	import { PermissionDeniedError } from "@/lib/permissions";
 12	import { InvalidSlugError } from "@/lib/slug";
 13	import { AlreadyArchivedError } from "@/lib/soft-delete";
 14	import { TenantScopeError } from "@/lib/tenant";
 15	import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
 16	import { ZodError, type ZodIssue } from "zod";
 17	
 18	export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
 19	  unauthorized: 401,
 20	  forbidden: 403,
 21	  not_found: 404,
 22	  validation_failed: 422,
 23	  conflict: 409,
 24	  rate_limited: 429,
 25	  plan_limit_exceeded: 402,
 26	  tenant_scope_violation: 403,
 27	  internal_error: 500,
 28	};
 29	
 30	/** True for the error classes this module knows how to translate faithfully. */
 31	export function isDomainError(error: unknown): boolean {
 32	  return (
 33	    error instanceof PermissionDeniedError ||
 34	    error instanceof TenantScopeError ||
 35	    error instanceof FeatureDisabledError ||
 36	    error instanceof AlreadyArchivedError ||
 37	    error instanceof InvalidSlugError ||
 38	    error instanceof ZodError
 39	  );
 40	}
 41	
 42	/** Collapses a `ZodError` into the `field → messages` map forms consume. */
 43	export function fieldErrorsFromZod(
 44	  error: ZodError,
 45	): Readonly<Record<string, readonly string[]>> {
 46	  const fields: Record<string, string[]> = {};
 47	  for (const issue of error.issues as readonly ZodIssue[]) {
 48	    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
 49	    (fields[key] ??= []).push(issue.message);
 50	  }
 51	  return fields;
 52	}
 53	
 54	export function toAppError(error: unknown): AppErrorShape {
 55	  if (error instanceof ZodError) {
 56	    return {
 57	      code: "validation_failed",
 58	      message: "Please correct the highlighted fields.",
 59	      fieldErrors: fieldErrorsFromZod(error),
 60	    };
 61	  }
 62	
 63	  if (error instanceof PermissionDeniedError) {
 64	    return {
 65	      code: "forbidden",
 66	      message: error.message,
 67	      meta: {
 68	        action: error.action,
 69	        resourceKind: error.decision.resourceKind,
 70	        reason: error.decision.reason,
 71	      },
 72	    };
 73	  }
 74	
 75	  if (error instanceof TenantScopeError) {
 76	    return {
 77	      code: "tenant_scope_violation",
 78	      message: "That resource belongs to a different organization.",
 79	      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
 80	    };
 81	  }
 82	
 83	  if (error instanceof FeatureDisabledError) {
 84	    return {
 85	      code: "forbidden",
 86	      message: error.message,
 87	      meta: { flag: error.flag },
 88	    };
 89	  }
 90	
 91	  if (error instanceof AlreadyArchivedError) {
 92	    return {
 93	      code: "conflict",
 94	      message: error.message,
 95	      meta: { entity: error.entity, id: error.id },
 96	    };
 97	  }
 98	
 99	  if (error instanceof InvalidSlugError) {
100	    return {
101	      code: "validation_failed",
102	      message: error.message,
103	      fieldErrors: { slug: [error.message] },
104	      meta: { value: error.value },
105	    };
106	  }
107	
108	  return {
109	    code: "internal_error",
110	    message:
111	      error instanceof Error ? error.message : "Something went wrong. Try again.",
112	  };
113	}
114	
115	/** The failure envelope a Server Action returns instead of throwing. */
116	export function toActionResult(error: unknown): ActionResult<never> {
117	  return {
118	    ok: false,
119	    error: toAppError(error),
120	    submittedAt: new Date().toISOString(),
121	  };
122	}

