    27	
    28	describe("services/member-service", () => {
    29	  // can(actor, "member:update_role", …) gates the change; a member cannot self-promote.
    30	  it("refuses a role change to an actor without member:update_role", async () => {
    31	    const tenant = await createTenant("member-role-forbidden", "growth");
    32	    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    33	    if (!target) throw new Error("fixture member missing");
    34	
    35	    await expect(
    36	      memberService.updateMemberRole(tenant.actors.member, {
    37	        orgId: tenant.org.id,
    38	        memberId: target.id,
    39	        role: "admin",
    40	      }),
    41	    ).rejects.toBeInstanceOf(PermissionDeniedError);
    42	  });
    43	
    44	  // The org must always retain at least one owner.
    45	  it("refuses to demote the last remaining owner", async () => {
    46	    const tenant = await createTenant("member-last-owner-demote", "growth");
    47	    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    48	    if (!ownerMember) throw new Error("fixture owner missing");
    49	
    50	    await expect(
    51	      memberService.updateMemberRole(tenant.actors.owner, {
    52	        orgId: tenant.org.id,
    53	        memberId: ownerMember.id,
    54	        role: "admin",
    55	      }),
    56	    ).rejects.toThrow(/at least one owner/);
    57	  });
    58	
    59	  // Demoting an owner is fine while another owner exists.
    60	  it("allows demoting an owner when another owner remains", async () => {
    61	    const tenant = await createTenant("member-second-owner", "growth");
    62	    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    63	    const adminMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    64	    if (!ownerMember || !adminMember) throw new Error("fixture member missing");
    65	
    66	    // Promote the admin to owner first, so two owners exist.
    67	    await memberService.updateMemberRole(tenant.actors.owner, {
    68	      orgId: tenant.org.id,
    69	      memberId: adminMember.id,
    70	      role: "owner",
    71	    });
    72	
    73	    const demoted = await memberService.updateMemberRole(tenant.actors.owner, {
    74	      orgId: tenant.org.id,
    75	      memberId: ownerMember.id,
    76	      role: "admin",
    77	    });
    78	
    79	    expect(demoted.role).toBe("admin");
    80	  });
    81	
    82	  // member.role_changed carries both the previous and the new role.
    83	  it("emits member.role_changed with from and to", async () => {
    84	    const tenant = await createTenant("member-role-emit", "growth");
    85	    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    86	    if (!target) throw new Error("fixture member missing");
    87	
    88	    let off: Unsubscribe | undefined;
    89	    const received = await new Promise((resolve) => {
    90	      off = subscribe("member.role_changed", (payload) => resolve(payload));
    91	      void memberService.updateMemberRole(tenant.actors.owner, {
    92	        orgId: tenant.org.id,
    93	        memberId: target.id,
    94	        role: "member",
    95	      });
    96	    });
    97	    off?.();
    98	
    99	    expect(received).toMatchObject({
   100	      orgId: tenant.org.id,
   101	      memberId: target.id,
   102	      from: "admin",
   103	      to: "member",
   104	    });
   105	  });
   106	
   107	  // Removing the last owner is refused for the same invariant.
   108	  it("refuses to remove the last remaining owner", async () => {
   109	    const tenant = await createTenant("member-last-owner-remove", "growth");
   110	    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
   111	    if (!ownerMember) throw new Error("fixture owner missing");
   112	
   113	    await expect(
   114	      memberService.removeMember(tenant.actors.owner, {
   115	        orgId: tenant.org.id,
   116	        memberId: ownerMember.id,
   117	      }),
   118	    ).rejects.toThrow(/at least one owner/);
   119	  });
   120	
   121	  // member.removed carries the memberId and userId that left.
   122	  it("emits member.removed when a member is removed", async () => {
   123	    const tenant = await createTenant("member-remove-emit", "growth");
   124	    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
   125	    if (!target) throw new Error("fixture member missing");
   126	
   127	    let off: Unsubscribe | undefined;
   128	    const received = await new Promise((resolve) => {
   129	      off = subscribe("member.removed", (payload) => resolve(payload));
   130	      void memberService.removeMember(tenant.actors.owner, {
   131	        orgId: tenant.org.id,
   132	        memberId: target.id,
   133	      });
   134	    });
   135	    off?.();
   136	
   137	    expect(received).toMatchObject({
   138	      orgId: tenant.org.id,
   139	      memberId: target.id,
   140	      userId: tenant.userIds.viewer,
   141	    });
   142	  });
   143	});
