  orgId: OrgId,
  memberId: MemberId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .get();
  return row ? toMember(row) : null;
}

/** Like `findMemberById`, but a removed member reads as absent. */
export async function findLiveMemberById(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.id, memberId),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

/**
 * Which of `userIds` are suspended members of the org. Removed members are
 * never reported, whatever status their row still carries.
 */
export async function findSuspendedUserIds(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<UserId>> {
  if (userIds.length === 0) return new Set();

  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.userId, [...userIds]),
        eq(members.status, "suspended"),
        liveMemberPredicate(),
      ),
    )
    .all();

  return new Set(rows.map((row) => row.userId as UserId));
}

