  actor: Actor,
  input: MemberSuspensionInput,
): Promise<Member> {
  return setSuspension(actor, input, "suspended");
}

/** Lifts a suspension. A member who is not suspended is returned unchanged. */
export async function reinstateMember(
  actor: Actor,
  input: MemberSuspensionInput,
): Promise<Member> {
  return setSuspension(actor, input, "active");
}

/**
 * The shared body of suspend and reinstate. The refusals run before the
 * already-in-that-state check, so a forbidden call is refused whatever the
 * member's current status is.
 */
async function setSuspension(
  actor: Actor,
  input: MemberSuspensionInput,
  target: "active" | "suspended",
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findLiveMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:remove", memberResource(member));

  if (member.userId === actor.userId) {
    throw new Error("You cannot suspend or reinstate yourself");
  }
  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error(
      `A ${actor.role} cannot suspend or reinstate a ${member.role}`,
    );
  }

  const alreadyInTarget =
    target === "suspended"
      ? member.status === "suspended"
      : member.status !== "suspended";
  if (alreadyInTarget) return member;

  if (target === "suspended") {
    await assertLastOwnerRetained(input.orgId, input.memberId, "member");
  }

  const updated = await memberRepo.updateMemberStatus(
    input.orgId,
    input.memberId,
    target,
  );

  await emit(target === "suspended" ? "member.suspended" : "member.reinstated", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    userId: updated.userId,
  });

  return updated;
}

/**
 * Refuses new work for a user who is a suspended member of the org. A user who
 * is not a live member at all is left to the callers' existing checks.
 */
export async function assertNotSuspended(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const member = await memberRepo.findMember(orgId, userId);
  if (member?.status === "suspended") throw new MemberSuspendedError(userId);
}

/**
 * Turns a (user, org) pair into the `Actor` every service method takes. The
 * only place an `Actor` is minted from stored state — jobs and the session
 * layer both come through here.
 */
export async function resolveActor(
  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") return null;

  return { userId, orgId, role: member.role };
}

/**
 * Throws when applying `nextRole` to `memberId` would leave the organization
 * without an owner. Only owners who are not suspended count: a suspended owner
 * does not keep the workspace ownable. Exported because the demote, remove and
 * suspend paths all need it, and the invariant must not be stated twice.
 */
export async function assertLastOwnerRetained(
  orgId: OrgId,
  memberId: MemberId,
  nextRole: Role,
): Promise<void> {
  if (nextRole === "owner") return;

  const member = await memberRepo.findMemberById(orgId, memberId);
  if (!member || member.role !== "owner") return;

  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: OWNER_SCAN_LIMIT,
    cursor: null,
  });

  const remaining = page.items.filter((row) => row.id !== memberId);
  if (remaining.length === 0) {
    throw new Error(
      "An organization must keep at least one owner; transfer ownership first",
    );
  }
}

